# Sector label -> profile. Matched on lower-case keywords in the scanned company's sector label (the keyword list
# is checked in order, so more specific entries come first).
_SECTOR_KEYWORDS = [
    ('finance', ('banking', 'bank', 'insurance', 'financial', 'asset management', 'investment')),
    ('energy', ('energy and utilities', 'energy', 'utilities', 'utility', 'power')),
    ('waste', ('waste management', 'environmental services', 'recycling')),
    ('construction', ('construction', 'infrastructure', 'real estate', 'property')),
    ('transport', ('transport', 'logistics', 'shipping', 'aviation', 'delivery')),
    ('textile', ('fashion', 'textile', 'apparel', 'clothing', 'garment')),
    ('retail', ('food retail', 'supermarket', 'discount', 'retail', 'grocery')),
    ('hospitality', ('accommodation', 'hospitality', 'hotel', 'food service', 'catering', 'restaurant', 'leisure', 'tourism', 'arts, entertainment')),
    ('agri', ('agriculture', 'farming', 'agricultural', 'livestock', 'dairy farming')),
    ('manufacturing', ('pharmaceutical',)),
    ('food', ('food and beverage', 'food manufacturing', 'beverage', 'brewery', 'ingredients', 'flavors', 'nutrition')),
    ('digital', ('digital', 'technology', 'software', 'telecom', 'it services')),
    ('manufacturing', ('manufacturing', 'chemicals', 'chemical', 'metals', 'materials', 'pharmaceutical', 'agrochemical', 'automotive', 'mining', 'industrial')),
    ('services', ('professional', 'business services', 'staffing', 'human resources', 'education', 'health', 'veterinary', 'media', 'facilities', 'consult')),
]


def profile_for_sector(sector_label):
    low = str(sector_label or '').lower()
    for profile, words in _SECTOR_KEYWORDS:
        if any(w in low for w in words):
            return profile
    return 'general'


def example(key, sector_label='', subject=''):
    """The fictional example for `key` (see EXAMPLES), adapted to the sector profile of `sector_label`. A broad claim
    (key generic / default) about a PRODUCT, range or collection (`subject` == 'product') gets a product-level fact
    instead of a company-level one."""
    profile = profile_for_sector(sector_label)
    if subject == 'product' and key in ('generic', 'default'):
        key = 'product'
    text = OVERRIDES.get(profile, {}).get(key) or EXAMPLES.get(key)
    if not text:
        return ''
    tokens = dict(PROFILES['general'])
    tokens.update(PROFILES.get(profile, {}))
    tokens['Thing'] = tokens['thing'][:1].upper() + tokens['thing'][1:]
    # a few examples need a generic fact per sector
    return text.format(**tokens)


